mapper.select:
SELECT c.id, c.user_id userId, c.file_md5 fileMd5, c.file_name fileName, c.file_url fileUrl, c.is_dir isDir, c.is_valid isValid, c.file_size fileSize, c.file_path filePath, c.create_time uploadTime, c.storage_type storageType, c.extend_name extendName, c.update_time updateTime, c.delete_time deleteTime, cs.school_name schoolName, u.actual_name userName FROM t_wp_user_file c LEFT JOIN t_base_user u ON c.user_id = u.id LEFT JOIN t_school_manage cs on cs.id = c.school_id WHERE c.is_valid =1 and u.is_valid =1 and c.status in(0,1)
AND EXISTS ( select 1 from t_wp_user_file_label ufl where ufl.file_id = c.id and ufl.is_valid = 1 AND ufl.label_id IN
#{item}
)
AND (u.actual_name like #{likeName} or c.file_name like #{likeName})
and c.storage_type = #{query.storageType}
and c.create_time >= #{query.startTime} and c.create_time <= #{query.endTime}
and c.user_id = #{query.userId}
and c.school_id = #{query.schoolId}
and c.extent_name = #{query.extentName}
order BY c.create_time desc
